$page=max(1,(int)($_GET['page']??1));$q=trim($_GET['q']??'');$status=$_GET['status']??'';$rating=(int)($_GET['rating']??0);
$where='1=1';$args=[];if($q!==''){$where.=' AND (p.name LIKE ? OR r.author_name LIKE ? OR r.email LIKE ? OR r.body LIKE ?)';$args=array_fill(0,4,'%'.$q.'%');}
if(in_array($status,['published','hidden'])){$where.=' AND r.status=?';$args[]=$status;}if($rating>=1&&$rating<=5){$where.=' AND r.rating=?';$args[]=$rating;}
$total=(int)scalar('SELECT COUNT(*) FROM product_reviews r JOIN products p ON p.id=r.product_id WHERE '.$where,$args);
$reviews=rows('SELECT r.*,p.name product_name FROM product_reviews r JOIN products p ON p.id=r.product_id WHERE '.$where.' ORDER BY r.created_at DESC,r.id DESC LIMIT 25 OFFSET '.(($page-1)*25),$args);
?>
<form class="admin-toolbar"><input type="search" name="q" placeholder="Search product, customer or review…" value="<?= h($q) ?>"><select name="status"><option value="">All visibility</option><option value="published" <?= $status==='published'?'selected':'' ?>>Published</option><option value="hidden" <?= $status==='hidden'?'selected':'' ?>>Hidden</option></select><select name="rating"><option value="">All ratings</option><?php for($star=5;$star>=1;$star--): ?><option value="<?= $star ?>" <?= $rating===$star?'selected':'' ?>><?= $star ?> stars</option><?php endfor; ?></select><button class="tf-button">Filter reviews</button><?php if($q!==''||$status!==''||$rating): ?><a class="tf-button style-3" href="<?= url('admin/reviews.php') ?>">Clear</a><?php endif; ?><span><?= $total ?> reviews</span></form>
<div class="wg-box"><p class="body-text mb-20">Hidden reviews are excluded from public ratings and counts.</p><div class="table-scroll"><table class="admin-table"><thead><tr><th>Product</th><th>Author</th><th>Rating</th><th>Review</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($reviews as $review): ?><tr><td><?= h($review['product_name']) ?></td><td><?= h($review['author_name']) ?><br><small><?= h($review['created_at']) ?></small></td><td><?= (int)$review['rating'] ?> / 5</td><td><?= nl2br(h($review['body'])) ?></td><td><?= h($review['status']) ?></td><td><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="moderate_review"><input type="hidden" name="id" value="<?= (int)$review['id'] ?>"><input type="hidden" name="status" value="<?= $review['status']==='published'?'hidden':'published' ?>"><button class="tf-button style-3"><?= $review['status']==='published'?'Hide':'Publish' ?></button></form></td></tr><?php endforeach; ?></tbody></table></div></div>
